import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CfmV7b-z.js";const u=JSON.parse('{"title":"templeo","description":"","frontmatter":{"layout":"home","hero":{"name":"templeo","text":"Native template literals, compiled for reuse","tagline":"A zero-dependency JavaScript template engine with portable renderers, nested includes, debugging, and extensible caching.","image":{"src":"/android-chrome-192x192.png","alt":"templeo"},"actions":[{"theme":"brand","text":"The Basics","link":"/guide/1-basics"},{"theme":"brand","text":"Cache","link":"/guide/2-cache"},{"theme":"alt","text":"API Reference","link":"/api/"},{"theme":"alt","text":"GitHub","link":"https://github.com/ugate/templeo"}]},"features":[{"icon":"💯","title":"Pure template literals","details":"Use built-in ECMAScript template literal syntax without a custom parser or template language."},{"icon":"🌐","title":"Stand-alone rendering","details":"Compiled rendering functions are portable and do not depend on templeo internals at render time."},{"icon":"⛓️","title":"Nested and parameterized includes","details":"Resolve reusable partials at compile time or render time and pass parameters into their isolated scope."},{"icon":"🏧","title":"Extensible caching","details":"Keep templates in memory or use the bundled database and file-system cache implementations."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function l(o,e,s,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="details" tabindex="-1">templeo <a class="header-anchor" href="#details" aria-label="Permalink to &quot;templeo {#details}&quot;">​</a></h1><p><code>templeo</code> is a <strong>zero-dependency</strong> template engine that uses built-in JavaScript/ECMAScript <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Template_literals" target="_blank" rel="noreferrer">Template Literals</a>. There is no regular-expression parser or special template syntax—just native ES template literals.</p><p>For more details, see <a href="/templeo/guide/1-basics">The Basics</a>, <a href="/templeo/guide/2-cache">Cache</a>, <a href="/templeo/guide/3-examples">Examples</a>, and the <a href="/templeo/api/">API Reference</a>.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>💯% PURE</strong> — No special syntax is required. Everything is part of the ECMAScript Template Literals specification, and a single <code>Engine</code> can output HTML, DOM nodes, JSON, YAML, or virtually any other format.</li><li><strong>🌱 Grows with the language</strong> — New template literal syntax and language features are immediately usable without a <code>templeo</code> parser update.</li><li><strong>🌐 Stand-Alone Rendering</strong> — Once compiled, a rendering function no longer depends on <code>templeo</code> internals and can be serialized, deserialized, or served from another source.</li><li><strong>🛡️ Secure</strong> — Compilation is sandboxed from local scope, and portable renderers remain isolated from the scope in which they were compiled.</li><li><strong>⛓️ Parameterized/Nested Includes</strong> — Reusable partials can be <a href="/templeo/guide/1-basics#include">included</a> at compile time or render time, with parameters confined to the included partial.</li><li><strong>🐞 Debugging</strong> — Compiled templates remain accessible through VM <code>sourceURL</code> values or module imports/requires for direct debugging.</li><li><strong>🧠 Extensible</strong> — Register helper functions for use in template literal expressions, while rendered output remains independent of <code>templeo</code>.</li><li><strong>🛎️ Auto Fetch</strong> — Templates, partials, and context can be fetched automatically at compile time or render time from HTTP/S sources.</li><li><strong>🏧 Caching</strong> — Templates are cached in memory by default. Bundled extensions support <a href="/templeo/guide/2-cache#db">IndexedDB/LevelDB</a> and the <a href="/templeo/guide/2-cache#fs">Node.js file system</a>.</li></ul>',5)])])}const h=t(n,[["render",l]]);export{u as __pageData,h as default};
